<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/app.php';
require_once dirname(__DIR__) . '/includes/admin-auth.php';
require_once dirname(__DIR__) . '/includes/blog/blog-functions.php';
require_once dirname(__DIR__) . '/includes/blog/blog-admin-actions.php';
require_once dirname(__DIR__) . '/includes/blog/blog-settings.php';
$user=mg_require_admin_page_any(['admin.blog.view','admin.blog.manage']);$canManage=mg_admin_permission_user_has($user,'admin.blog.manage');$pdo=mg_db();$schema=mg_blog_schema_ready($pdo);$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ if(!$canManage){mg_admin_page_forbidden('admin.blog.manage');} elseif(!mg_verify_csrf((string)($_POST['csrf_token']??''))){$error='Security token expired. Refresh and try again.';} elseif(!$schema['ready']){$error='Blog SQL migration is required before managing posts.';} else {$action=(string)($_POST['action']??'');$postId=(int)($_POST['post_id']??0); if($action==='status'){$target=(string)($_POST['status']??'draft');$notice=mg_blog_update_post_status($pdo,$postId,$target)?'Post moved to '.$target.'.':'No post was updated.';} elseif($action==='duplicate'){$errs=[];$newId=mg_blog_duplicate_post($pdo,$postId,$user,$errs);if($newId){header('Location: /admin/blog-editor.php?id='.$newId.'&saved=1',true,303);exit;}$error=$errs?implode(' ',$errs):'Post could not be duplicated.';} elseif($action==='delete'){$notice=mg_blog_soft_delete_post($pdo,$postId)?'Post moved to deleted history.':'No post was deleted.';}}}
$status=(string)($_GET['status']??'');$search=trim((string)($_GET['q']??''));$categoryId=(int)($_GET['category_id']??0);$posts=[];$counts=['all'=>0,'draft'=>0,'published'=>0,'scheduled'=>0,'archived'=>0];$categories=[];if($schema['ready']){$posts=mg_blog_admin_posts($pdo,['status'=>$status,'search'=>$search,'category_id'=>$categoryId,'limit'=>80]);$counts=mg_blog_status_counts($pdo);$categories=mg_blog_categories($pdo,false);}function mg_admin_blog_status_form(int $id,string $status,string $label): string{return '<form method="post" action="/admin/blog-posts.php">'.mg_csrf_field().'<input type="hidden" name="action" value="status"><input type="hidden" name="post_id" value="'.$id.'"><input type="hidden" name="status" value="'.mg_e($status).'"><button type="submit">'.mg_e($label).'</button></form>';}function mg_admin_blog_duplicate_form(int $id): string{return '<form method="post" action="/admin/blog-posts.php">'.mg_csrf_field().'<input type="hidden" name="action" value="duplicate"><input type="hidden" name="post_id" value="'.$id.'"><button type="submit">Duplicate</button></form>';}
$page_title='Content Studio | Microgifter Admin';$page_section='account';$header_mode='account';$page_body_class='mg-admin-blog-page';$page_styles=['/assets/css/admin-shell.css','/assets/css/admin-blog.css','/assets/css/admin-blog-settings.css'];$adminActive='blog';require dirname(__DIR__).'/includes/header.php';
?>
<section class="mg-app-shell mg-admin-app"><?php require dirname(__DIR__).'/includes/admin-sidebar.php'; ?><div class="mg-app-workspace mg-admin-workspace"><main class="mg-admin-blog-shell"><header class="mg-admin-blog-hero"><div><a class="mg-admin-blog-back" href="/account-admin.php">← Admin dashboard</a><span class="mg-eyebrow">Content Studio</span><h1>Blog manager</h1><p>Publish founder notes, merchant education, product updates, investor thinking, and category-building content for Microgifter.</p></div><div class="mg-admin-blog-actions"><a class="mg-btn mg-btn-soft" href="/blog.php" target="_blank" rel="noopener">View public blog</a><a class="mg-btn mg-btn-ghost" href="/admin/blog-categories.php">Categories</a><a class="mg-btn mg-btn-ghost" href="/admin/blog-media.php">Media</a><a class="mg-btn mg-btn-ghost" href="/admin/blog-settings.php">Settings</a><?php if($canManage): ?><a class="mg-btn mg-btn-primary" href="/admin/blog-editor.php">Create post</a><?php endif; ?></div></header><?php if(!$schema['ready']): ?><section class="mg-admin-blog-alert"><strong>SQL migration required.</strong><span>Run <code>database/microgifter_blog_module.sql</code> before creating or publishing posts.</span></section><?php endif; ?><?php if($notice!==''): ?><section class="mg-admin-blog-alert is-success"><strong>Saved.</strong><span><?= mg_e($notice) ?></span></section><?php endif; ?><?php if($error!==''): ?><section class="mg-admin-blog-alert is-error"><strong>Action failed.</strong><span><?= mg_e($error) ?></span></section><?php endif; ?><section class="mg-admin-blog-stats"><?php foreach([['all','All posts'],['published','Published'],['draft','Drafts'],['scheduled','Scheduled'],['archived','Archived']] as [$key,$label]): ?><a class="<?= $status===$key||($key==='all'&&$status==='')?'is-active':'' ?>" href="/admin/blog-posts.php<?= $key==='all'?'':'?status='.rawurlencode($key) ?>"><span><?= mg_e($label) ?></span><strong><?= (int)($counts[$key]??0) ?></strong></a><?php endforeach; ?></section><section class="mg-admin-blog-panel"><form class="mg-admin-blog-filters" method="get" action="/admin/blog-posts.php"><label>Search<input type="search" name="q" value="<?= mg_e($search) ?>" placeholder="Title, slug, or excerpt"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(mg_blog_statuses() as $opt): ?><option value="<?= mg_e($opt) ?>" <?= $status===$opt?'selected':'' ?>><?= mg_e(ucfirst($opt)) ?></option><?php endforeach; ?></select></label><label>Category<select name="category_id"><option value="0">All categories</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= $categoryId===(int)$cat['id']?'selected':'' ?>><?= mg_e((string)$cat['name']) ?></option><?php endforeach; ?></select></label><button class="mg-btn mg-btn-soft" type="submit">Filter</button><a class="mg-btn mg-btn-ghost" href="/admin/blog-posts.php">Reset</a></form><?php if(!$schema['ready']): ?><div class="mg-admin-blog-empty"><h2>Blog tables are not installed yet.</h2><p>The UI is wired. Import the migration to activate content management.</p></div><?php elseif(!$posts): ?><div class="mg-admin-blog-empty"><h2>No blog posts found.</h2><p>Create the first article or adjust your filters.</p><?php if($canManage): ?><a class="mg-btn mg-btn-primary" href="/admin/blog-editor.php">Create first post</a><?php endif; ?></div><?php else: ?><div class="mg-admin-blog-table-wrap"><table class="mg-admin-blog-table"><thead><tr><th>Post</th><th>Category</th><th>Status</th><th>Published</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($posts as $post): $postStatus=(string)$post['status'];$quality=mg_blog_get_admin_post($pdo,(int)$post['id'])?:$post;$issues=mg_blog_seo_issues($quality); ?><tr><td><div class="mg-admin-blog-title-cell"><span class="mg-admin-blog-thumb" style="<?= !empty($post['featured_image'])?'background-image:url('.mg_e((string)$post['featured_image']).')':'' ?>"></span><div><strong><?= mg_e((string)$post['title']) ?></strong><span><?= mg_e((string)$post['slug']) ?></span><small><?= mg_e(mb_substr((string)$post['excerpt'],0,120)) ?></small><div class="mg-admin-blog-quality <?= $issues?'':'is-good' ?>"><?php if($issues): foreach(array_slice($issues,0,4) as $issue): ?><span><?= mg_e($issue) ?></span><?php endforeach; else: ?><span>SEO ready</span><?php endif; ?></div></div></div></td><td><?= mg_e((string)($post['category_name']??'Uncategorized')) ?></td><td><span class="mg-admin-blog-status is-<?= mg_e($postStatus) ?>"><?= mg_e($postStatus) ?></span><?= !empty($post['is_featured'])?'<span class="mg-admin-blog-featured">Featured</span>':'' ?></td><td><?= mg_e(mg_blog_format_date($post['published_at']??null)) ?></td><td><?= mg_e(mg_blog_format_date($post['updated_at']??null)) ?></td><td><div class="mg-admin-blog-row-actions"><a href="/admin/blog-editor.php?id=<?= (int)$post['id'] ?>">Edit</a><a href="/admin/blog-preview.php?id=<?= (int)$post['id'] ?>" target="_blank" rel="noopener">Preview</a><?php if($postStatus==='published'): ?><a href="/blog-post.php?slug=<?= rawurlencode((string)$post['slug']) ?>" target="_blank" rel="noopener">Public</a><?php endif; ?><?php if($canManage): ?><?= mg_admin_blog_duplicate_form((int)$post['id']) ?><?php if($postStatus!=='published'){echo mg_admin_blog_status_form((int)$post['id'],'published','Publish');} ?><?php if($postStatus!=='draft'){echo mg_admin_blog_status_form((int)$post['id'],'draft','Draft');} ?><?php if($postStatus!=='archived'){echo mg_admin_blog_status_form((int)$post['id'],'archived','Archive');} ?><form method="post" action="/admin/blog-posts.php"><?= mg_csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="post_id" value="<?= (int)$post['id'] ?>"><button type="submit">Remove</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main></div></section><?php require dirname(__DIR__).'/includes/footer.php'; ?>
